"""Compile the real BookmarkCrafting against isolated game/API fixtures; no Gradle."""
import argparse
from pathlib import Path
import subprocess
import tempfile

parser = argparse.ArgumentParser()
parser.add_argument('--java-home', type=Path, required=True)
args = parser.parse_args()
root = Path(__file__).resolve().parents[2]
stubs = {
'net/minecraft/item/ItemStack.java': '''package net.minecraft.item;
public class ItemStack { public String id; public int count; public ItemStack(String id,int n){this.id=id;count=n;} public boolean isEmpty(){return count<=0||id.isEmpty();} public int getCount(){return count;} public int getMaxCount(){return 64;} public void setCount(int n){count=n;} public ItemStack copy(){return new ItemStack(id,count);} public static boolean canCombine(ItemStack a,ItemStack b){return a.id.equals(b.id);} }''',
'net/minecraft/screen/slot/Slot.java': '''package net.minecraft.screen.slot; import net.minecraft.item.*; public class Slot { public Object inventory; public int index; public boolean take=true; public ItemStack stack=new ItemStack("",0); public ItemStack getStack(){return stack;} public int getIndex(){return index;} public boolean canTakeItems(Object p){return take;} }''',
'net/minecraft/screen/ScreenHandler.java': '''package net.minecraft.screen; import java.util.*; import net.minecraft.screen.slot.*; import net.minecraft.item.*; public class ScreenHandler { public int syncId=1; public List<Slot> slots=new ArrayList<>(); public ItemStack cursor=new ItemStack("",0); public ItemStack getCursorStack(){return cursor;} }''',
'net/minecraft/client/gui/screen/ingame/HandledScreen.java': '''package net.minecraft.client.gui.screen.ingame; import net.minecraft.screen.*; public class HandledScreen<T extends ScreenHandler> { public T handler; public HandledScreen(T h){handler=h;} public T getScreenHandler(){return handler;} }''',
'net/minecraft/client/MinecraftClient.java': '''package net.minecraft.client; import java.util.*; import net.minecraft.screen.*; import net.minecraft.item.*;
public class MinecraftClient { public static final MinecraftClient INSTANCE=new MinecraftClient(); public Object currentScreen,world=new Object(),interactionManager=new Object(); public Player player=new Player(); public boolean onThread=true; public boolean isOnThread(){return onThread;} public void setScreen(Object s){currentScreen=s;} public static MinecraftClient getInstance(){return INSTANCE;} public static class Player { public int age; public ScreenHandler currentScreenHandler,playerScreenHandler=new ScreenHandler(); public Inventory inv=new Inventory(); public Inventory getInventory(){return inv;} } public static class Inventory { public List<ItemStack> stacks=new ArrayList<>(); public Inventory(){for(int i=0;i<41;i++)stacks.add(new ItemStack("",0));} public int size(){return stacks.size();} public ItemStack getStack(int i){return stacks.get(i);} } }''',
'dev/emi/emi/api/stack/EmiIngredient.java': '''package dev.emi.emi.api.stack; import java.util.*; public interface EmiIngredient { List<EmiStack> getEmiStacks(); default long getAmount(){return 1;} default float getChance(){return 1;} default boolean isEmpty(){return getEmiStacks().isEmpty()||getEmiStacks().stream().allMatch(s->s.id.isEmpty());} }''',
'dev/emi/emi/api/stack/EmiStack.java': '''package dev.emi.emi.api.stack; import java.util.*; import net.minecraft.item.*; public class EmiStack implements EmiIngredient { public final String id; public long amount=1; public float chance=1; public EmiStack remainder; public EmiStack(String id){this.id=id;} public List<EmiStack> getEmiStacks(){return List.of(this);} public long getAmount(){return amount;} public float getChance(){return chance;} public boolean isEmpty(){return id.isEmpty();} public EmiStack getRemainder(){return remainder==null?new EmiStack(""):remainder;} public ItemStack getItemStack(){return new ItemStack(id,(int)amount);} public boolean isEqual(EmiStack s){return id.equals(s.id);} public static EmiStack of(ItemStack s){EmiStack e=new EmiStack(s.id);e.amount=s.count;return e;} }''',
'dev/emi/emi/api/recipe/EmiRecipe.java': '''package dev.emi.emi.api.recipe; import java.util.*; import dev.emi.emi.api.stack.*; public interface EmiRecipe { List<EmiIngredient> getInputs(); List<EmiStack> getOutputs(); }''',
'dev/emi/emi/api/recipe/EmiPlayerInventory.java': '''package dev.emi.emi.api.recipe; public class EmiPlayerInventory { public static final EmiPlayerInventory INSTANCE=new EmiPlayerInventory(); public boolean available=true; public EmiRecipe checked; public static EmiPlayerInventory of(Object p){return INSTANCE;} public boolean canCraft(EmiRecipe r,long n){checked=r;return available;} }''',
'dev/emi/emi/api/recipe/handler/EmiRecipeHandler.java': '''package dev.emi.emi.api.recipe.handler; import dev.emi.emi.api.recipe.*; import net.minecraft.screen.*; import net.minecraft.client.gui.screen.ingame.*; public interface EmiRecipeHandler<T extends ScreenHandler> { boolean supportsRecipe(EmiRecipe r); EmiPlayerInventory getInventory(HandledScreen<T> s); boolean canCraft(EmiRecipe r,EmiCraftContext<T> c); boolean craft(EmiRecipe r,EmiCraftContext<T> c); }''',
'dev/emi/emi/api/recipe/handler/StandardRecipeHandler.java': '''package dev.emi.emi.api.recipe.handler; import java.util.*; import dev.emi.emi.api.recipe.*; import net.minecraft.screen.*; import net.minecraft.screen.slot.*; import net.minecraft.client.gui.screen.ingame.*; public interface StandardRecipeHandler<T extends ScreenHandler> extends EmiRecipeHandler<T> { Slot getOutputSlot(T h); List<Slot> getCraftingSlots(T h); default List<Slot> getCraftingSlots(EmiRecipe r,T h){return getCraftingSlots(h);} List<Slot> getInputSources(T h); default EmiPlayerInventory getInventory(HandledScreen<T> s){return EmiPlayerInventory.INSTANCE;} default boolean canCraft(EmiRecipe r,EmiCraftContext<T> c){return true;} default boolean craft(EmiRecipe r,EmiCraftContext<T> c){return true;} }''',
'dev/emi/emi/registry/EmiRecipeFiller.java': '''package dev.emi.emi.registry; import java.util.*; import dev.emi.emi.api.recipe.*; import dev.emi.emi.api.stack.*; import dev.emi.emi.api.recipe.handler.*; import net.minecraft.screen.*; import net.minecraft.item.*; import net.minecraft.client.gui.screen.ingame.*;
public class EmiRecipeFiller { public static EmiRecipeHandler<?> handler; public static int calls,amount=1; public static EmiCraftContext.Destination destination; public static boolean accepted=true,missing=false; public static EmiRecipe lookup,collected,filled; public static List<ItemStack> sent; @SuppressWarnings("unchecked") public static <T extends ScreenHandler> EmiRecipeHandler<T> getFirstValidHandler(EmiRecipe r,HandledScreen<T>s){lookup=r;return (EmiRecipeHandler<T>)handler;} public static <T extends ScreenHandler> List<ItemStack> getStacks(StandardRecipeHandler<T> h,EmiRecipe r,HandledScreen<T>s,int a){collected=r;amount=a;h.getCraftingSlots(r,s.getScreenHandler());if(missing)return null;List<ItemStack> list=new ArrayList<>();for(EmiIngredient i:r.getInputs()){ItemStack stack=i.isEmpty()?new ItemStack("",0):i.getEmiStacks().get(0).getItemStack();stack.setCount((int)i.getAmount()*(a+5));list.add(stack);}return list;} public static <T extends ScreenHandler> boolean clientFill(StandardRecipeHandler<T> h,EmiRecipe r,HandledScreen<T>s,List<ItemStack>st,EmiCraftContext.Destination d){calls++;filled=r;sent=st;destination=d;return accepted;} }''',
'dev/emi/emi/platform/EmiClient.java': '''package dev.emi.emi.platform; import java.util.*; import dev.emi.emi.api.recipe.*; import dev.emi.emi.api.recipe.handler.*; import dev.emi.emi.registry.*; import net.minecraft.screen.*; import net.minecraft.item.*; import net.minecraft.client.gui.screen.ingame.*; public class EmiClient {public static boolean onServer=false; public static <T extends ScreenHandler>void sendFillRecipe(StandardRecipeHandler<T>h,HandledScreen<T>s,int id,int action,List<ItemStack>st,EmiRecipe r){EmiRecipeFiller.calls++;EmiRecipeFiller.filled=r;EmiRecipeFiller.sent=st;EmiRecipeFiller.destination=action==2?EmiCraftContext.Destination.INVENTORY:EmiCraftContext.Destination.NONE;} }''',
'dev/emi/emi/runtime/EmiBookmarkGroups.java': '''package dev.emi.emi.runtime; import java.util.*; import dev.emi.emi.api.recipe.*;
public class EmiBookmarkGroups { public static final class Group{} public static final class Row {public EmiRecipe recipe; public boolean input; public long batches; public Group group=new Group(); public Row(EmiRecipe r,long b,boolean i){recipe=r;batches=b;input=i;}} public static List<Row> plain=List.of(),offset=List.of(); public static Map<EmiRecipe,EmiRecipe>effective=new IdentityHashMap<>(); public static EmiPlayerInventory lastInventory; public static EmiRecipe effectiveRecipe(Group g,EmiRecipe r){return effective.getOrDefault(r,r);} public static List<Row> executionRows(Group g,EmiPlayerInventory i){lastInventory=i;return i==null?plain:offset;} }''',
'dev/emi/emi/runtime/EmiSidebars.java': '''package dev.emi.emi.runtime; import dev.emi.emi.api.recipe.*; public class EmiSidebars {public static EmiRecipe last;public static void craft(EmiRecipe r){last=r;}}''',
'dev/emi/emi/runtime/EmiLog.java': '''package dev.emi.emi.runtime; public class EmiLog {public static void error(String s,Throwable t){throw new AssertionError(s,t);}}''',
}
with tempfile.TemporaryDirectory(prefix='emi-bookmark-crafting-') as directory:
    source = Path(directory) / 'src'
    for name, text in stubs.items():
        target = source / name
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(text, encoding='utf-8')
    files = list(source.rglob('*.java')) + [
        root / 'xplat/src/main/java/dev/emi/emi/runtime/BookmarkCrafting.java',
        root / 'xplat/src/main/java/dev/emi/emi/api/recipe/handler/EmiCraftContext.java',
        root / 'tests/bookmark-crafting/src/dev/emi/emi/runtime/BookmarkCraftingChecks.java',
    ]
    annotation = source / 'org/jetbrains/annotations/ApiStatus.java'
    annotation.parent.mkdir(parents=True, exist_ok=True)
    annotation.write_text('package org.jetbrains.annotations; public class ApiStatus { public @interface Internal {} }', encoding='utf-8')
    files.append(annotation)
    classes = Path(directory) / 'classes'
    subprocess.run([str(args.java_home/'bin/javac.exe'), '--release', '17', '-encoding', 'UTF-8', '-d', str(classes), *map(str, files)], check=True)
    subprocess.run([str(args.java_home/'bin/java.exe'), '-ea', '-cp', str(classes), 'dev.emi.emi.runtime.BookmarkCraftingChecks'], check=True)
